// endpointMeta returns Endpoint.Metadata with the ordered openapi block for key; hide adds
// scope "server" (HIDE_METADATA).
func endpointMeta(key string, hide bool) map[string]any {
	m := map[string]any{}
	if hide {
		m["scope"] = "server"
	}
	if raw, ok := openapiSpecs[key]; ok {
		v, err := jsonx.Parse([]byte(raw))
		if err != nil {
			panic(err)
		}
		m["openapi"] = v
	}
	return m
}
